/**
 * The Expo starter imports CSS files (global.css, animated-icon.module.css)
 * via Metro's CSS support. `expo-env.d.ts` (generated on first `expo start`)
 * normally supplies these declarations; this file keeps `tsc --noEmit` green
 * before that file exists and is harmless alongside it.
 */
declare module '*.css';
declare module '*.module.css';